 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; # [doc = " Processes all .rs files found in src directory"] fn process_all_rust_files (paths : & CratePaths , config : & SplitDeclsConfig , collected_module_names : & mut Vec < Ident > , item_count : & mut usize , common_uses : & TokenStream , dry_run : bool ,) -> Result < () > { let src_dir = paths . crate_path . join ("src") ; let rust_files = find_all_rust_files (& src_dir) ? ; for rust_file in rust_files { if let Some (file_name) = rust_file . file_name () { if file_name == "lib.rs" || file_name == "main.rs" { continue ; } } if rust_file . to_string_lossy () . contains ("/decls/") { continue ; } println ! ("Processing file: {}" , rust_file . display ()) ; let file_content = fs :: read_to_string (& rust_file) ? ; let file_ast : syn :: File = syn :: parse_str (& file_content) ? ; let rel_path = rust_file . strip_prefix (& src_dir) . unwrap_or (& rust_file) ; let path_str = rel_path . to_string_lossy () . replace ("/" , "_") . replace ("\\" , "_") . replace (".rs" , "") ; for item in & file_ast . items { if let Some (decl) = declaration_extractor :: extract_single_declaration (item , * item_count) { let module_name_str = format ! ("{}_decls_{}_{}" , paths . crate_name . replace ("-" , "_") . replace ("." , "_") , path_str . replace ("-" , "_") . replace ("." , "_") , decl . name) ; let module_name_ident = Ident :: new (& module_name_str , Span :: call_site ()) ; collected_module_names . push (module_name_ident . clone ()) ; declaration_writer :: write_declaration_file (decl . clone () , paths , config , dry_run , common_uses , module_name_ident ,) ? ; print ! ("{}, " , decl . name) ; * item_count += 1 ; } } } Ok (()) }